#include "Aevrynd/NetworkTransport3D.h"
#include <algorithm>
#include <limits>
#include <stdexcept>

namespace Aevrynd {
LoopbackNetworkTransport3D::LoopbackNetworkTransport3D(LoopbackNetworkSettings3D value):settings_(value),state_(value.seed?value.seed:1){if(!settings_.maximumEndpoints||!settings_.maximumQueuedPackets||!settings_.maximumQueuedBytes||!settings_.maximumPacketBytes||settings_.maximumPacketBytes>settings_.maximumQueuedBytes||settings_.lossPermille>1000||settings_.duplicatePermille>1000||settings_.reorderPermille>1000||settings_.minimumJitterTicks>settings_.maximumJitterTicks)throw std::invalid_argument("Invalid loopback network settings");}
std::uint64_t LoopbackNetworkTransport3D::Random()noexcept{state_^=state_>>12;state_^=state_<<25;state_^=state_>>27;return state_*2685821657736338717ull;}
bool LoopbackNetworkTransport3D::RegisterEndpoint(NetworkEndpoint3D endpoint){if(!endpoint||endpoints_.size()>=settings_.maximumEndpoints||std::ranges::find(endpoints_,endpoint)!=endpoints_.end())return false;endpoints_.push_back(endpoint);stats_.endpoints=endpoints_.size();return true;}
bool LoopbackNetworkTransport3D::UnregisterEndpoint(NetworkEndpoint3D endpoint){const auto found=std::ranges::find(endpoints_,endpoint);if(found==endpoints_.end())return false;endpoints_.erase(found);for(auto it=queue_.begin();it!=queue_.end();)if(it->packet.source==endpoint||it->packet.destination==endpoint){stats_.queuedBytes-=it->packet.bytes.size();it=queue_.erase(it);}else ++it;stats_.endpoints=endpoints_.size();stats_.queuedPackets=queue_.size();stats_.queuedBytes=stats_.queuedBytes;return true;}
bool LoopbackNetworkTransport3D::Enqueue(NetworkEndpoint3D source,NetworkEndpoint3D destination,std::span<const std::byte> bytes,std::uint64_t delay,bool duplicate){if(queue_.size()>=settings_.maximumQueuedPackets||bytes.size()>settings_.maximumQueuedBytes-stats_.queuedBytes||delay>(std::numeric_limits<std::uint64_t>::max)()-tick_){++stats_.backpressureRejected;return false;}Queued item{};item.packet={source,destination,tick_+delay,std::vector<std::byte>(bytes.begin(),bytes.end())};item.order=nextOrder_;if(nextOrder_==(std::numeric_limits<std::uint64_t>::max)()){++stats_.backpressureRejected;return false;}++nextOrder_;queue_.push_back(std::move(item));stats_.queuedBytes+=bytes.size();stats_.queuedPackets=queue_.size();stats_.peakQueuedPackets=(std::max)(stats_.peakQueuedPackets,stats_.queuedPackets);stats_.peakQueuedBytes=(std::max)(stats_.peakQueuedBytes,stats_.queuedBytes);if(duplicate)++stats_.duplicated;return true;}
bool LoopbackNetworkTransport3D::Send(NetworkEndpoint3D source,NetworkEndpoint3D destination,std::span<const std::byte> bytes){if(!source||!destination||bytes.empty()||bytes.size()>settings_.maximumPacketBytes||std::ranges::find(endpoints_,source)==endpoints_.end()||std::ranges::find(endpoints_,destination)==endpoints_.end()){++stats_.invalidRejected;return false;}++stats_.sent;if((settings_.burstPeriodTicks&&tick_%settings_.burstPeriodTicks<settings_.burstLengthTicks)||(Random()%1000)<settings_.lossPermille){++stats_.lost;return true;}const auto range=std::uint64_t(settings_.maximumJitterTicks-settings_.minimumJitterTicks)+1;std::uint64_t delay=settings_.minimumJitterTicks+(Random()%range);if((Random()%1000)<settings_.reorderPermille){delay+=1+Random()%3;++stats_.reordered;}if(!Enqueue(source,destination,bytes,delay,false))return false;if((Random()%1000)<settings_.duplicatePermille)(void)Enqueue(source,destination,bytes,delay+Random()%2,true);return true;}
void LoopbackNetworkTransport3D::AdvanceTo(std::uint64_t value){if(value<tick_)return;stats_.advancedTicks+=value-tick_;tick_=value;}
bool LoopbackNetworkTransport3D::TryReceive(NetworkEndpoint3D endpoint,NetworkPacket3D& packet){auto found=queue_.end();for(auto it=queue_.begin();it!=queue_.end();++it)if(it->packet.destination==endpoint&&it->packet.deliveryTick<=tick_&&(found==queue_.end()||it->packet.deliveryTick<found->packet.deliveryTick||(it->packet.deliveryTick==found->packet.deliveryTick&&it->order<found->order)))found=it;if(found==queue_.end())return false;packet=std::move(found->packet);stats_.queuedBytes-=packet.bytes.size();queue_.erase(found);stats_.queuedPackets=queue_.size();++stats_.delivered;return true;}
void LoopbackNetworkTransport3D::Reset(){queue_.clear();endpoints_.clear();tick_=0;nextOrder_=1;state_=settings_.seed?settings_.seed:1;stats_={};}
std::size_t LoopbackNetworkTransport3D::TrimUnusedMemory(){const auto before=endpoints_.capacity()*sizeof(NetworkEndpoint3D);endpoints_.shrink_to_fit();return before-endpoints_.capacity()*sizeof(NetworkEndpoint3D);}
}
